namespace GateControl {
 public static class Program {
  [STAThread] public static int Main(string[] args){
   if(args.Length==4&&(args[0]=="--signal-stop"||args[0]=="--hide-console"))return NativeConsole.Run(args);
   if(args.Length==2&&args[0]=="--self-test")return Tests.Run(args[1]);
   if(args.Length==4&&args[0]=="--integration")return Tests.Integration(args[1],args[2],args[3]);
   if(args.Length==2&&args[0]=="--render-preview"){try{System.Windows.Media.RenderOptions.ProcessRenderMode=System.Windows.Interop.RenderMode.SoftwareOnly;Directory.CreateDirectory(args[1]);var app=new Application();var controller=new Controller(Path.Combine(args[1],"preview-profile"));controller.RenderPreviews(args[1]);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(args[1],"render-error.txt"),ex.ToString());return 1;}}
   string data=args.Length==2&&args[0]=="--data-dir"?Path.GetFullPath(args[1]):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"GateControl");
   if(Path.GetFileNameWithoutExtension(Assembly.GetExecutingAssembly().Location).EndsWith(".QA",StringComparison.OrdinalIgnoreCase))data=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"qa-profile");
   bool created;using(var mutex=new Mutex(true,"Local\\GateControl-"+WindowsIdentity.GetCurrent().User.Value,out created)){
    if(!created){MessageBox.Show("开服器已经运行，请切换到已有窗口。","GATE Control");return 1;}
    try{Directory.CreateDirectory(data);var app=new Application();app.DispatcherUnhandledException+=(s,e)=>{MessageBox.Show(e.Exception.Message,"操作未完成",MessageBoxButton.OK,MessageBoxImage.Warning);e.Handled=true;};var controller=new Controller(data);app.Run(controller.Window);return 0;}
    catch(Exception e){MessageBox.Show("程序无法启动：\n"+e.Message,"GATE Control",MessageBoxButton.OK,MessageBoxImage.Error);return 1;}
   }
  }
 }
 public class Controller {
  public Window Window;readonly string dataDir;Profile profile;readonly ServerRunner runner;readonly Countdown countdown=new Countdown();readonly DispatcherTimer timer;
  readonly List<SandboxOption> schema=SandboxOption.All();readonly Dictionary<string,Control> sandboxControls=new Dictionary<string,Control>();readonly Dictionary<string,FrameworkElement> sandboxRows=new Dictionary<string,FrameworkElement>();
  readonly Queue<string> events=new Queue<string>();string sandboxContext="",adminContext="";bool busy,closing,wasAlive;int ticks;DateTime launchTime;
  T C<T>(string name) where T:class{return Window.FindName(name) as T;}
  TextBox T(string name){return C<TextBox>(name);} TextBlock L(string name){return C<TextBlock>(name);} CheckBox K(string name){return C<CheckBox>(name);}
  void On(string name,Action action){C<Button>(name).Click+=(s,e)=>Guard(action);}
  void AsyncOn(string name,Func<Task> action){C<Button>(name).Click+=async(s,e)=>{try{await action();}catch(Exception ex){Error(ex);}};}
  void Guard(Action action){try{action();}catch(Exception e){Error(e);}}
  void Error(Exception e){Status("操作未完成："+e.Message);MessageBox.Show(Window,e.Message,"请检查",MessageBoxButton.OK,MessageBoxImage.Warning);}
  void Status(string message){L("FooterText").Text=message;events.Enqueue("["+DateTime.Now.ToString("HH:mm:ss")+"] "+message);while(events.Count>80)events.Dequeue();}
  bool Confirm(string message){return MessageBox.Show(Window,message,"GATE Control",MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes;}
  public Controller(string dir){
   dataDir=dir;Window=(Window)XamlReader.Parse(Files.Resource("MainWindow.xaml"));runner=new ServerRunner(dir);
   string loadWarning="";try{profile=Files.Load<Profile>(Path.Combine(dir,"profile.xml"));var a=profile.ServerPassword;var b=profile.AdminPassword;}catch(Exception e){profile=new Profile();loadWarning="旧配置无法读取，原文件保留，请重新设置。"+e.Message;}
   if(Paths.Valid(AppDomain.CurrentDomain.BaseDirectory))profile.Root=AppDomain.CurrentDomain.BaseDirectory.TrimEnd('\\');
   if(!Paths.Valid(profile.Root))profile.Root=Paths.Detect();
   BuildSandbox();Fill();Wire();
   try{if(runner.Recover(profile)){wasAlive=true;launchTime=runner.Process.StartTime;Status("已重新连接本程序上次启动的服务器。倒计时需重新设置。");}}catch(Exception e){Status("未恢复上次进程："+e.Message);}
   RefreshOverview();UpdateState();timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};timer.Tick+=Tick;timer.Start();
   Window.Closing+=OnClosing;if(loadWarning!="")Window.Loaded+=(s,e)=>MessageBox.Show(Window,loadWarning,"配置提示");
  }
  void Fill(){T("RootBox").Text=profile.Root;T("NameBox").Text=profile.Name;T("WorldBox").Text=profile.World;T("PlayersBox").Text=profile.Players.ToString();T("PortBox").Text=profile.Port.ToString();T("QueryBox").Text=profile.QueryPort.ToString();C<PasswordBox>("ServerPasswordBox").Password=profile.ServerPassword;C<PasswordBox>("AdminPasswordBox").Password=profile.AdminPassword;C<ComboBox>("IpBox").Items.Clear();C<ComboBox>("IpBox").Items.Add("");foreach(string ip in Launch.LocalAddresses())C<ComboBox>("IpBox").Items.Add(ip);C<ComboBox>("IpBox").Text=profile.Ip;C<ComboBox>("PlatformBox").SelectedIndex=Array.IndexOf(new[]{"","PC","Playstation","Xbox"},profile.Platform);K("LanBox").IsChecked=profile.Lan;K("LocalIpsBox").IsChecked=profile.LocalIps;K("PerfBox").IsChecked=profile.Perf;K("ConsoleBox").IsChecked=profile.Console;K("ManageSandboxBox").IsChecked=profile.ManageSandbox;
   if(profile.Sandbox.Count>0){SetSandbox(profile.Sandbox.ToDictionary(x=>x.Key,x=>x.Value,StringComparer.OrdinalIgnoreCase));sandboxContext=profile.SandboxContext;L("SandboxContextText").Text="使用上次保存的规则；可读取当前世界文件进行同步。";}
   else if(Paths.Valid(profile.Root)){try{LoadSandbox(false);}catch(Exception e){Status(e.Message);}}else SetSandbox(new Dictionary<string,string>());
  }
  Profile Collect(){var p=profile.Clone();p.Root=Paths.NormalizeRoot(T("RootBox").Text);p.Name=T("NameBox").Text.Trim();p.World=T("WorldBox").Text;p.Ip=C<ComboBox>("IpBox").Text.Trim();p.Players=Integer(T("PlayersBox").Text,"玩家上限");p.Port=Integer(T("PortBox").Text,"游戏端口");p.QueryPort=Integer(T("QueryBox").Text,"查询端口");p.ServerPassword=C<PasswordBox>("ServerPasswordBox").Password;p.AdminPassword=C<PasswordBox>("AdminPasswordBox").Password;var selected=C<ComboBox>("PlatformBox").SelectedItem as ComboBoxItem;p.Platform=selected==null?"":Convert.ToString(selected.Tag);p.Lan=K("LanBox").IsChecked==true;p.LocalIps=K("LocalIpsBox").IsChecked==true;p.Perf=K("PerfBox").IsChecked==true;p.Console=K("ConsoleBox").IsChecked==true;p.ManageSandbox=K("ManageSandboxBox").IsChecked==true;p.SandboxContext=sandboxContext;p.Sandbox=CollectSandbox();Launch.Validate(p);return p;}
  int Integer(string value,string title){int n;if(!Int32.TryParse(value,out n))throw new ArgumentException(title+"需要填写整数。");return n;}
  void Persist(Profile p){Files.Save(Path.Combine(dataDir,"profile.xml"),p);profile=p;RefreshOverview();}
  Profile Location(){var p=new Profile{Root=Paths.NormalizeRoot(T("RootBox").Text),World=T("WorldBox").Text};Paths.ValidateWorld(p.World);return p;}
  void RequireStopped(Profile p){if(busy||runner.Alive||Launch.OtherServer(p.Root))throw new InvalidOperationException("请先停止该服务器，再修改文件或处理存档。");}
  void Wire(){
   string[] pages={"Overview","Settings","Sandbox","Schedule","Saves","Logs"};foreach(string page in pages){string current=page;C<RadioButton>("Nav"+page).Checked+=(s,e)=>Navigate(current);}
   On("GoSettingsButton",()=>Navigate("Settings"));On("BrowseButton",()=>{var path=PickFolder("选择专用服务器根目录",T("RootBox").Text);if(path!=null){T("RootBox").Text=Paths.NormalizeRoot(path);LoadSandbox(false);RefreshOverview();Status("已选择服务器目录。保存设置后会记住此位置。");}});
   On("DetectButton",()=>{var root=Paths.Detect();if(root=="")throw new DirectoryNotFoundException("未找到安装目录，请手动选择。");T("RootBox").Text=root;LoadSandbox(false);RefreshOverview();Status("已自动识别 Steam 服务器安装目录。");});
   On("SaveSettingsButton",()=>{Persist(Collect());Status("设置已保存，下次启动生效。");});On("PreviewButton",()=>{var p=Collect();MessageBox.Show(Window,Paths.Exe(p.Root)+"\n\n"+Launch.Arguments(p,true),"启动参数（密码已遮盖）");});
   AsyncOn("StartButton",()=>Start());AsyncOn("StopButton",()=>Stop(false));AsyncOn("RestartButton",()=>Stop(true));
   On("OpenGameButton",()=>OpenFolder(Location().Root));On("LoadSandboxButton",()=>{if(Confirm("读取当前世界会替换界面中尚未保存的沙盒修改，是否继续？"))LoadSandbox(true);});
   On("ResetSandboxButton",()=>{if(Confirm("将界面中全部沙盒规则恢复为官方默认值？保存或启动应用前不会修改存档文件。")){var p=Location();SetSandbox(new Dictionary<string,string>());sandboxContext=Paths.Context(p);L("SandboxContextText").Text="已恢复默认值，待保存："+p.World;}});
   On("SaveSandboxButton",()=>{var p=Collect();RequireStopped(p);if(sandboxContext!=Paths.Context(p))throw new InvalidOperationException("请先读取当前世界的规则。");Ini.SaveSandbox(p);Persist(p);Status("沙盒规则已保存到独立配置文件，启动时通过官方参数应用。");});T("SandboxSearch").TextChanged+=(s,e)=>FilterSandbox();
   On("ScheduleButton",()=>{if(!runner.Alive||busy||!runner.Health.Ready)throw new InvalidOperationException("请先等待世界正常加载，再安排定时任务。");double minutes;if(!Double.TryParse(T("MinutesBox").Text,NumberStyles.Float,CultureInfo.InvariantCulture,out minutes))throw new ArgumentException("请输入有效的分钟数。");countdown.Set(minutes,C<ComboBox>("TaskBox").SelectedIndex==1,K("RepeatBox").IsChecked==true);Status("倒计时已设置。");UpdateSchedule();});
   On("CancelScheduleButton",()=>{countdown.Cancel();Status("已取消定时任务。");UpdateSchedule();});
   AsyncOn("BackupButton",Backup);AsyncOn("ImportButton",Import);On("OpenSavesButton",()=>OpenFolder(Paths.Worlds(Location().Root)));On("OpenBackupsButton",()=>{string d=Path.Combine(dataDir,"Backups");Directory.CreateDirectory(d);OpenFolder(d);});
   On("LoadAdminButton",LoadAdmins);On("SaveAdminButton",SaveAdmins);On("OpenProfileButton",()=>OpenFolder(dataDir));On("RefreshLogsButton",RefreshLogs);
   On("ExportLogsButton",()=>{var d=new Microsoft.Win32.SaveFileDialog{Filter="日志文本|*.log",FileName="GateControl-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".log"};if(d.ShowDialog(Window)==true){File.WriteAllText(d.FileName,T("LogBox").Text,new UTF8Encoding(true));Status("当前显示的日志已导出。");}});
   On("ForceStopButton",()=>{if(runner.Alive&&Confirm("强制结束可能丢失尚未保存的世界进度。建议先在游戏内保存。仍要强制结束该进程吗？")){countdown.Cancel();runner.Process.Kill();Status("已请求强制结束；这不保证世界保存。");}});
   On("LaunchDocsButton",()=>OpenUrl("https://github.com/DFJacob/AbioticFactorDedicatedServer/wiki/Technical-%E2%80%90-Launch-Parameters"));On("SandboxDocsButton",()=>OpenUrl("https://github.com/DFJacob/AbioticFactorDedicatedServer/wiki/Technical-%E2%80%90-Sandbox-Options"));On("MigrationDocsButton",()=>OpenUrl("https://github.com/DFJacob/AbioticFactorDedicatedServer/wiki/Guide-%E2%80%90-Migrating-Saves"));
  }
  void Navigate(string page){var titles=new Dictionary<string,string>{{"Overview","控制中心"},{"Settings","服务器设置"},{"Sandbox","沙盒规则"},{"Schedule","定时任务"},{"Saves","存档与管理"},{"Logs","日志与帮助"}};var subtitles=new Dictionary<string,string>{{"Overview","把繁琐留给程序，把时间留给探索。"},{"Settings","从房间名称到网络端口，清晰配置你的服务器。"},{"Sandbox","48 项官方规则，塑造你的生存体验。"},{"Schedule","计划一次维护，或安排循环重启。"},{"Saves","管理世界文件，为每次探索保留退路。"},{"Logs","了解运行状态，查阅官方说明。"}};foreach(var name in titles.Keys)C<ScrollViewer>("Page"+name).Visibility=name==page?Visibility.Visible:Visibility.Collapsed;L("PageTitle").Text=titles[page];L("PageSubtitle").Text=subtitles[page];C<RadioButton>("Nav"+page).IsChecked=true;if(page=="Logs")Guard(RefreshLogs);if(page=="Saves")Guard(RefreshWorlds);}
  void BuildSandbox(){foreach(string group in schema.Select(x=>x.Group).Distinct()){var panel=new StackPanel();panel.Children.Add(new TextBlock{Text=group,FontSize=18,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,18)});var card=new Border{Style=(Style)Window.FindResource("Card"),Child=panel};C<StackPanel>("SandboxPanel").Children.Add(card);foreach(var o in schema.Where(x=>x.Group==group)){var row=new Grid{Margin=new Thickness(0,0,0,18)};row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(230)});var text=new StackPanel{Margin=new Thickness(0,0,18,0)};text.Children.Add(new TextBlock{Text=o.Title,FontWeight=FontWeights.SemiBold});text.Children.Add(new TextBlock{Text=o.Key,FontFamily=new FontFamily("Consolas"),Foreground=new SolidColorBrush(Color.FromRgb(130,153,132)),FontSize=11,Margin=new Thickness(0,4,0,2)});text.Children.Add(new TextBlock{Text=o.Hint+(o.Min!=""?" 范围 "+o.Min+"–"+o.Max+"。":""),Style=(Style)Window.FindResource("Muted"),FontSize=12});row.Children.Add(text);Control control;if(o.Kind=="bool"){var combo=new ComboBox();combo.Items.Add(new ComboBoxItem{Content="开启",Tag="True"});combo.Items.Add(new ComboBoxItem{Content="关闭",Tag="False"});control=combo;}else if(o.Kind.Contains("=")){var combo=new ComboBox();foreach(string choice in o.Kind.Split('|')){var a=choice.Split('=');combo.Items.Add(new ComboBoxItem{Content=a[1],Tag=a[0]});}control=combo;}else control=new TextBox();control.VerticalAlignment=VerticalAlignment.Center;control.ToolTip=o.Key;System.Windows.Automation.AutomationProperties.SetName(control,o.Title);Grid.SetColumn(control,1);row.Children.Add(control);sandboxControls[o.Key]=control;sandboxRows[o.Key]=row;panel.Children.Add(row);}}}
  void SetSandbox(Dictionary<string,string> values){foreach(var o in schema){string value;if(!values.TryGetValue(o.Key,out value))value=o.Default;var c=sandboxControls[o.Key];if(c is TextBox)((TextBox)c).Text=value;else{var combo=(ComboBox)c;var item=combo.Items.Cast<ComboBoxItem>().FirstOrDefault(x=>String.Equals(Convert.ToString(x.Tag),value,StringComparison.OrdinalIgnoreCase));if(item==null){item=new ComboBoxItem{Content="未识别值："+value,Tag=value};combo.Items.Add(item);}combo.SelectedItem=item;}}}
  List<SettingValue> CollectSandbox(){var result=new List<SettingValue>();bool validate=K("ManageSandboxBox").IsChecked==true;foreach(var o in schema){var c=sandboxControls[o.Key];string v=c is TextBox?((TextBox)c).Text:Convert.ToString(((ComboBoxItem)((ComboBox)c).SelectedItem).Tag);result.Add(new SettingValue(o.Key,validate?o.Normalize(v):v));}return result;}
  void FilterSandbox(){string q=T("SandboxSearch").Text.Trim();foreach(var o in schema)sandboxRows[o.Key].Visibility=(o.Title+o.Key+o.Group).IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0?Visibility.Visible:Visibility.Collapsed;}
  void LoadSandbox(bool notify){var p=Location();var path=Paths.Sandbox(p);SetSandbox(Ini.Read(File.Exists(path)?File.ReadAllText(path):"","SandboxSettings"));sandboxContext=Paths.Context(p);L("SandboxContextText").Text="当前世界："+p.World+"  ·  "+(File.Exists(path)?"已读取存档规则":"尚无规则文件，显示官方默认值");if(notify)Status("沙盒规则已读取。");}
  async Task Start(){if(busy)return;var p=Collect();Persist(p);busy=true;UpdateState();try{await Task.Run(()=>runner.Start(p));wasAlive=true;launchTime=DateTime.Now;ticks=0;Status("服务器进程已启动，正在加载。请查看日志确认可连接状态。");}finally{busy=false;UpdateState();}}
  async Task<bool> StopInternal(bool restart,bool scheduled){if(busy)return false;if(!runner.Alive){countdown.Cancel();return true;}busy=true;var p=runner.RunningProfile.Clone();bool repeat=scheduled&&countdown.Repeat;double minutes=countdown.Minutes;if(!scheduled)countdown.Cancel();UpdateState();try{Status("正在请求正常退出，最多等待 45 秒…");bool stopped=await runner.StopAsync();if(!stopped){countdown.Cancel();Status("服务器未在时限内退出。重启已取消；请检查日志，必要时手动强制结束。");return false;}runner.Clear();wasAlive=false;if(restart){await Task.Run(()=>runner.Start(p));launchTime=DateTime.Now;wasAlive=true;ticks=0;if(repeat)countdown.Set(minutes,true,true);Status("服务器已重启，等待地图加载。");}else{countdown.Cancel();Status("服务器进程已退出。");}return true;}finally{busy=false;UpdateState();UpdateSchedule();}}
  async Task Stop(bool restart){await StopInternal(restart,false);}
  async void Tick(object sender,EventArgs e){try{ticks++;bool alive=runner.Alive;if(wasAlive&&!alive&&!busy){int code=runner.Process==null?0:runner.Process.ExitCode;runner.Clear();wasAlive=false;countdown.Cancel();Status("服务器进程已退出，退出码 "+code+"；定时任务已取消。");}if(alive){var elapsed=DateTime.Now-runner.Process.StartTime;L("UptimeText").Text=((int)elapsed.TotalHours).ToString("00")+elapsed.ToString(@"\:mm\:ss");runner.Process.Refresh();L("MemoryText").Text=(runner.Process.WorkingSet64/1048576.0).ToString("N0")+" MB";if(ticks==2||ticks==6||ticks==12)runner.HideConsole();}else{L("UptimeText").Text="00:00:00";L("MemoryText").Text="—";}if(alive&&!busy&&ticks%2==0){bool hadFailure=runner.Health.SaveCorrupt;runner.RefreshHealth();if(!hadFailure&&runner.Health.SaveCorrupt){countdown.Cancel();Status("世界存档校验失败，计划已取消。请停止服务器后检查世界目录；进程存活不代表开服成功。");}}UpdateState();UpdateSchedule();if(ticks%2==0&&C<ScrollViewer>("PageLogs").Visibility==Visibility.Visible)RefreshLogs();if(!busy&&alive&&countdown.TakeDue(DateTime.UtcNow))await StopInternal(countdown.Restart,true);}catch(Exception ex){countdown.Cancel();Status("运行检查："+ex.Message);}}
  void UpdateState(){bool alive=runner.Alive;C<Button>("StartButton").IsEnabled=!alive&&!busy;C<Button>("StopButton").IsEnabled=alive&&!busy;C<Button>("RestartButton").IsEnabled=alive&&!busy&&!runner.Health.SaveCorrupt;C<Button>("ForceStopButton").IsEnabled=alive&&!busy;C<ScrollViewer>("PageSettings").IsEnabled=!alive&&!busy;C<ScrollViewer>("PageSandbox").IsEnabled=!alive&&!busy;C<ScrollViewer>("PageSaves").IsEnabled=!alive&&!busy;C<Button>("ScheduleButton").IsEnabled=alive&&!busy&&runner.Health.Ready;L("StatusBadge").Text=busy?"●  正在处理":alive?(runner.Health.SaveCorrupt?"●  存档错误":runner.Health.Ready?"●  世界已加载":"●  正在加载世界"):"●  未启动";L("HeroDetail").Text=alive&&runner.Health.SaveCorrupt?"启动失败：世界存档校验未通过。请停服后检查存档目录。":alive?"PID "+runner.Process.Id+"  ·  世界 "+runner.RunningProfile.World+"  ·  UDP "+runner.RunningProfile.Port:"确认设置后，启动你的协作生存世界。";}
  void RefreshOverview(){string root=T("RootBox").Text;L("DetectedPathText").Text=String.IsNullOrEmpty(root)?"尚未选择目录":root;L("PathStatusText").Text=Paths.Valid(root)?"✓  已找到服务器程序与内容目录":"需要选择完整的专用服务器目录。";L("HeroName").Text=String.IsNullOrWhiteSpace(T("NameBox").Text)?"你的地下设施，准备就绪。":T("NameBox").Text;}
  void UpdateSchedule(){if(countdown.DueUtc.HasValue){var left=countdown.DueUtc.Value-DateTime.UtcNow;if(left<TimeSpan.Zero)left=TimeSpan.Zero;string duration=((int)left.TotalHours).ToString("00")+left.ToString(@"\:mm\:ss");L("NextTaskText").Text=duration;L("ScheduleStatusText").Text=duration+" 后"+(countdown.Restart?"重启":"关闭");L("ScheduleDetailText").Text=countdown.DueUtc.Value.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss")+(countdown.Repeat?" · 循环执行":" · 单次任务");}else{L("NextTaskText").Text="未安排";L("ScheduleStatusText").Text="没有待执行的计划";L("ScheduleDetailText").Text="计划仅在开服器保持运行时有效。";}}
  void RefreshWorlds(){var p=Location();string path=Paths.Worlds(p.Root);L("WorldsText").Text=Directory.Exists(path)?"已有世界："+String.Join("、",Directory.GetDirectories(path).Select(Path.GetFileName)):"尚无世界存档；首次启动会创建。";}
  async Task Backup(){var p=Location();RequireStopped(p);string world=Paths.World(p);if(!Directory.Exists(world))throw new DirectoryNotFoundException("当前世界尚未生成存档。");string dest=Path.Combine(dataDir,"Backups",p.World+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6)+".zip");busy=true;UpdateState();try{await Task.Run(()=>{Files.ValidateTree(world);Directory.CreateDirectory(Path.GetDirectoryName(dest));ZipFile.CreateFromDirectory(world,dest,CompressionLevel.Optimal,true);});Status("备份完成："+dest);}finally{busy=false;UpdateState();}}
  async Task Import(){var p=Location();RequireStopped(p);string source=PickFolder("选择单个世界存档文件夹",Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData));if(source==null)return;string world=Path.GetFileName(source.TrimEnd('\\'));Paths.ValidateWorld(world);if(!Directory.EnumerateFiles(source,"*.sav",SearchOption.AllDirectories).Any())throw new InvalidDataException("所选文件夹内没有 .sav 文件，请选择实际世界存档。");string destination=Path.Combine(Paths.Worlds(p.Root),world);if(Directory.Exists(destination))throw new IOException("同名世界已存在。请先重命名导入文件夹，避免覆盖。");Files.EnsureNoLinks(Paths.Worlds(p.Root));Files.ValidateTree(source);if(Path.GetFullPath(destination).StartsWith(Path.GetFullPath(source).TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))throw new IOException("目标不能位于源文件夹内。");busy=true;UpdateState();string staging=destination+".import-"+Guid.NewGuid().ToString("N");try{await Task.Run(()=>{Files.CopyTree(source,staging);Directory.Move(staging,destination);});T("WorldBox").Text=world;LoadSandbox(false);Persist(Collect());RefreshWorlds();Status("世界已导入并设为当前世界："+world);}catch(Exception){Status("导入未完成。如留下 .import 临时目录，可检查后自行移除。");throw;}finally{busy=false;UpdateState();}}
  void LoadAdmins(){var p=Location();string path=Paths.Admin(p.Root);var ids=new List<string>();bool inside=false;if(File.Exists(path))foreach(var line in File.ReadAllLines(path)){string t=line.Trim();if(t.StartsWith("[")&&t.EndsWith("]")){inside=t.Equals("[Moderators]",StringComparison.OrdinalIgnoreCase);continue;}if(inside&&Regex.IsMatch(t,@"^Moderator\s*=",RegexOptions.IgnoreCase)){string id=t.Substring(t.IndexOf('=')+1).Trim();if(Regex.IsMatch(id,@"^\d{17}$"))ids.Add(id);}}T("ModeratorsBox").Text=String.Join(Environment.NewLine,ids);adminContext=Path.GetFullPath(path);Status("已读取管理员 SteamID；示例占位值不显示。");}
  void SaveAdmins(){var p=Location();RequireStopped(p);string path=Paths.Admin(p.Root);if(adminContext!=Path.GetFullPath(path))throw new InvalidOperationException("请先读取白名单，再编辑并保存。");var ids=T("ModeratorsBox").Text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).Distinct().ToList();if(ids.Any(x=>!Regex.IsMatch(x,@"^\d{17}$")))throw new ArgumentException("每行必须是 17 位数字 SteamID64。");Files.EnsureNoLinks(path);string before=File.Exists(path)?File.ReadAllText(path):"";Files.Atomic(path,new UTF8Encoding(true).GetBytes(Ini.ReplaceModerators(before,ids)),true);Status("管理员白名单已保存；原文件已备份，封禁列表已保留。");}
  void RefreshLogs(){string root=runner.Alive?runner.RunningProfile.Root:T("RootBox").Text;string path=Path.Combine(Paths.Saved(root),"Logs","AbioticFactor.log");string tail="暂无服务器日志。";if(File.Exists(path)){using(var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){long start=Math.Max(0,f.Length-128*1024);f.Seek(start,SeekOrigin.Begin);using(var r=new StreamReader(f,Encoding.UTF8,true)){if(start>0)r.ReadLine();tail=r.ReadToEnd();}}}string shown=String.Join(Environment.NewLine,events)+Environment.NewLine+"──────────────── 原生服务器日志（末尾） ────────────────"+Environment.NewLine+Launch.Redact(tail,runner.RunningProfile??profile);if(T("LogBox").Text!=shown){T("LogBox").Text=shown;T("LogBox").ScrollToEnd();}}
  string PickFolder(string title,string initial){using(var dialog=new Forms.FolderBrowserDialog{Description=title,ShowNewFolderButton=false,SelectedPath=Directory.Exists(initial)?initial:""}){return dialog.ShowDialog()==Forms.DialogResult.OK?dialog.SelectedPath:null;}}
  void OpenFolder(string path){if(!Directory.Exists(path))throw new DirectoryNotFoundException("目录尚不存在："+path);Process.Start(new ProcessStartInfo("explorer.exe","\""+path+"\""){UseShellExecute=true});}
  void OpenUrl(string url){Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}
  public void RenderPreviews(string directory){timer.Stop();var root=(FrameworkElement)Window.Content;root.Resources=Window.Resources;root.SetValue(TextElement.ForegroundProperty,Window.Foreground);root.SetValue(TextElement.FontFamilyProperty,Window.FontFamily);root.SetValue(TextElement.FontSizeProperty,Window.FontSize);((Grid)root).Background=Window.Background;Window.Content=null;foreach(string page in new[]{"Overview","Settings","Sandbox","Schedule","Saves","Logs"}){Navigate(page);root.Width=1180;root.Height=760;root.Measure(new Size(1180,760));root.Arrange(new Rect(0,0,1180,760));root.UpdateLayout();var bitmap=new RenderTargetBitmap(1180,760,96,96,PixelFormats.Pbgra32);bitmap.Render(root);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(directory,page+".png")))png.Save(stream);}Window.Close();}
  async void OnClosing(object sender,System.ComponentModel.CancelEventArgs e){if(closing)return;if(busy){e.Cancel=true;Status("请等待当前操作完成再退出。");return;}if(runner.Alive){e.Cancel=true;var result=MessageBox.Show(Window,"服务器仍在运行。\n\n是：正常停止服务器后退出。\n否：保留服务器运行，仅退出开服器（取消定时任务）。\n取消：返回窗口。","退出开服器",MessageBoxButton.YesNoCancel,MessageBoxImage.Question);if(result==MessageBoxResult.Cancel)return;try{if(result==MessageBoxResult.Yes&&!await StopInternal(false,false))return;countdown.Cancel();closing=true;timer.Stop();Window.Close();}catch(Exception ex){Error(ex);}}else{countdown.Cancel();timer.Stop();}}
 }
}


